BEGIN;
CREATE TABLE IF NOT EXISTS tigeriq_schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees (employee_id text PRIMARY KEY,display_name text NOT NULL,roles text[] NOT NULL DEFAULT '{}',permissions text[] NOT NULL DEFAULT '{}',capabilities text[] NOT NULL DEFAULT '{}',state text NOT NULL CHECK(state IN('active','suspended','revoked')),concurrency_limit integer NOT NULL CHECK(concurrency_limit BETWEEN 1 AND 100),last_heartbeat_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS devices (device_id text PRIMARY KEY,platform text NOT NULL,public_key_fingerprint text,state text NOT NULL CHECK(state IN('pending','active','lost','revoked','replaced')),last_heartbeat_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS employee_device_bindings (binding_id text PRIMARY KEY,employee_id text NOT NULL REFERENCES employees(employee_id),device_id text NOT NULL REFERENCES devices(device_id),state text NOT NULL CHECK(state IN('pending','active','revoked','replaced')),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_employee_device_binding ON employee_device_bindings(employee_id,device_id) WHERE state='active';
CREATE TABLE IF NOT EXISTS ai_providers (provider_id text PRIMARY KEY,provider text NOT NULL,model text NOT NULL,independence_key text NOT NULL,state text NOT NULL CHECK(state IN('active','degraded','disabled')),secret_ref text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,last_heartbeat_at timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS goals (goal_id text PRIMARY KEY,idempotency_key text NOT NULL UNIQUE,objective text NOT NULL,priority text NOT NULL CHECK(priority IN('P0','P1','P2','P3')),constraints text[] NOT NULL DEFAULT '{}',max_parallelism integer NOT NULL CHECK(max_parallelism BETWEEN 1 AND 100),status text NOT NULL CHECK(status IN('planned','running','blocked','failed','completed','cancelled')),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (job_id text PRIMARY KEY,goal_id text REFERENCES goals(goal_id),idempotency_key text NOT NULL,definition_hash text NOT NULL,title text NOT NULL,objective text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,target_employee_id text REFERENCES employees(employee_id),preferred_provider_id text REFERENCES ai_providers(provider_id),required_permissions text[] NOT NULL DEFAULT '{}',required_capabilities text[] NOT NULL DEFAULT '{}',allowed_worker_kinds text[] NOT NULL,expected_evidence text[] NOT NULL CHECK(cardinality(expected_evidence)>0),max_attempts integer NOT NULL CHECK(max_attempts BETWEEN 1 AND 10),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0 AND attempts<=max_attempts),stage text NOT NULL CHECK(stage IN('queued','leased','reviewing','judging','done','failed','cancelled')),independent_review boolean NOT NULL DEFAULT true,judge_required boolean NOT NULL DEFAULT false,priority text NOT NULL CHECK(priority IN('P0','P1','P2','P3')),last_failure_code text,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(NOT judge_required OR independent_review));
CREATE UNIQUE INDEX IF NOT EXISTS uq_jobs_idempotency_target ON jobs((COALESCE(target_employee_id,'')),idempotency_key);
CREATE INDEX IF NOT EXISTS ix_jobs_queue ON jobs(stage,priority,created_at) WHERE stage='queued';
CREATE TABLE IF NOT EXISTS job_dependencies (job_id text NOT NULL REFERENCES jobs(job_id) ON DELETE CASCADE,depends_on_job_id text NOT NULL REFERENCES jobs(job_id),PRIMARY KEY(job_id,depends_on_job_id),CHECK(job_id<>depends_on_job_id));
CREATE TABLE IF NOT EXISTS job_scopes (job_id text NOT NULL REFERENCES jobs(job_id) ON DELETE CASCADE,scope_key text NOT NULL,PRIMARY KEY(job_id,scope_key),CHECK(length(trim(scope_key))>0));
CREATE INDEX IF NOT EXISTS ix_job_scopes_scope ON job_scopes(scope_key);
CREATE TABLE IF NOT EXISTS leases (lease_id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(job_id),employee_id text NOT NULL REFERENCES employees(employee_id),device_id text REFERENCES devices(device_id),binding_id text REFERENCES employee_device_bindings(binding_id),worker_kind text NOT NULL CHECK(worker_kind IN('ai','pc01','device','tool','human')),worker_independence_key text NOT NULL,attempt integer NOT NULL CHECK(attempt>0),status text NOT NULL CHECK(status IN('active','completed','expired','revoked')),lease_token_hash text NOT NULL CHECK(lease_token_hash ~ '^[a-f0-9]{64}$'),leased_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,revoke_reason text,CHECK(expires_at>leased_at));
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_lease_per_job ON leases(job_id) WHERE status='active';
CREATE INDEX IF NOT EXISTS ix_leases_expiry ON leases(status,expires_at);
CREATE INDEX IF NOT EXISTS ix_leases_employee_active ON leases(employee_id,status,expires_at);
CREATE TABLE IF NOT EXISTS results (result_id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(job_id),lease_id text NOT NULL REFERENCES leases(lease_id),attempt integer NOT NULL CHECK(attempt>0),employee_id text NOT NULL REFERENCES employees(employee_id),device_id text REFERENCES devices(device_id),binding_id text REFERENCES employee_device_bindings(binding_id),status text NOT NULL CHECK(status IN('completed','failed')),output jsonb,failure_code text,failure_message text,retriable boolean,result_hash text NOT NULL CHECK(result_hash ~ '^[a-f0-9]{64}$'),completed_at timestamptz NOT NULL,created_at timestamptz NOT NULL,UNIQUE(job_id,attempt),CHECK((status='completed' AND failure_code IS NULL) OR (status='failed' AND failure_code IS NOT NULL)));
CREATE TABLE IF NOT EXISTS reviews (review_id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(job_id),attempt integer NOT NULL CHECK(attempt>0),role text NOT NULL CHECK(role IN('reviewer','judge')),reviewer_id text NOT NULL,independence_key text NOT NULL,verdict text NOT NULL CHECK(verdict IN('pass','needs-work','fail')),conclusion text NOT NULL,retriable boolean NOT NULL DEFAULT true,reviewed_at timestamptz NOT NULL,UNIQUE(job_id,attempt,role));
CREATE TABLE IF NOT EXISTS evidence (evidence_id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(job_id) ON DELETE CASCADE,result_id text REFERENCES results(result_id) ON DELETE CASCADE,review_id text REFERENCES reviews(review_id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN('text','json','log','commit','url','screenshot')),ref text NOT NULL,summary text,sha256 text CHECK(sha256 IS NULL OR sha256 ~ '^[a-fA-F0-9]{64}$'),created_at timestamptz NOT NULL,CHECK((result_id IS NOT NULL)::integer+(review_id IS NOT NULL)::integer=1));
CREATE INDEX IF NOT EXISTS ix_evidence_job ON evidence(job_id,kind);
CREATE TABLE IF NOT EXISTS prompts (prompt_id text PRIMARY KEY,job_id text NOT NULL REFERENCES jobs(job_id) ON DELETE CASCADE,provider_id text REFERENCES ai_providers(provider_id),model text,prompt_text text NOT NULL,request_hash text NOT NULL,attempt integer NOT NULL CHECK(attempt>0),created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_prompts_job ON prompts(job_id,attempt);
CREATE TABLE IF NOT EXISTS prompt_metrics (metric_id text PRIMARY KEY,prompt_id text NOT NULL REFERENCES prompts(prompt_id) ON DELETE CASCADE,input_tokens integer CHECK(input_tokens IS NULL OR input_tokens>=0),output_tokens integer CHECK(output_tokens IS NULL OR output_tokens>=0),latency_ms integer CHECK(latency_ms IS NULL OR latency_ms>=0),provider_attempts integer NOT NULL CHECK(provider_attempts>=1),failover_count integer NOT NULL DEFAULT 0 CHECK(failover_count>=0),success boolean NOT NULL,error_code text,recorded_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS heartbeats (heartbeat_id text PRIMARY KEY,employee_id text NOT NULL REFERENCES employees(employee_id),device_id text REFERENCES devices(device_id),provider_id text REFERENCES ai_providers(provider_id),health text NOT NULL CHECK(health IN('ok','degraded','offline')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,observed_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_heartbeats_employee_observed ON heartbeats(employee_id,observed_at DESC);
INSERT INTO tigeriq_schema_migrations(version) VALUES('001_operational_state_v1') ON CONFLICT(version) DO NOTHING;
COMMIT;
